import random

def reference(nums, target):
    seen = {}
    for i, v in enumerate(nums):
        complement = target - v
        if complement in seen:
            return [seen[complement], i]
        seen[v] = i
    return []

def brute(nums, target):
    n = len(nums)
    for i in range(n):
        for j in range(i + 1, n):
            if nums[i] + nums[j] == target:
                return [i, j]
    return []

def gen(n, rnd):
    n = max(2, n)
    val_range = 10 ** 6
    target = rnd.randint(-val_range, val_range)
    a = rnd.randint(-val_range, val_range)
    b = target - a
    nums = [a, b]
    existing = {a, b}
    for _ in range(2, n):
        while True:
            v = rnd.randint(-val_range, val_range)
            if (target - v) not in existing:
                break
        nums.append(v)
        existing.add(v)
    idx = list(range(n))
    rnd.shuffle(idx)
    shuffled = [None] * n
    for pos, val in zip(idx, nums):
        shuffled[pos] = val
    return [shuffled, target]

